import argparse,json,subprocess
from pathlib import Path
from defhs_frozen_closure_utils import dump,sha256
ROOT=Path(__file__).resolve().parents[1];RUN=ROOT/'runs/RS-DEFHS-SYSTEM3-WAVE1-001'
def read(n):return json.loads((RUN/n).read_text())
def compact(q):return {k:q[k] for k in ['macro_f1','fold_macro_f1','per_class_f1','confusion'] if k in q}|{'strata':{k:v for k,v in q['strata'].items() if k in ['CLEAN','nonretrieval','int16','int32','prompt_singleton','repeated_prompt']}}
def rowmetrics(d):return {v:compact(q) for v,q in d.items()}
def point(d,v='VB',s=None):return d[v]['macro_f1'] if s is None else d[v]['strata'][s]['macro_f1']
def fmt(x):return '—' if x is None else f'{x:.5f}'
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--final',action='store_true');args=ap.parse_args()
 assert read('W1_PREFLIGHT.json')['status']=='PASS' and read('W1_SECONDARY_CONFIRMATION.json')['status']=='COMPLETE'
 cpu=read('W1_CPU_PAIR_RESULTS.json');nested=read('W1_NESTED_FUSION_RESULTS.json');a=read('W1_E2V_ADAPTATION_RESULTS.json');corr=a['strict_same_initialization_correction'];b=read('W1_AST_RESULTS.json');bl=read('W1_FIXED_BLEND_RESULTS.json');va=read('W1_CONFIRMATION_VA_seed20260930.json');s2b=read('W1_CONFIRMATION_VB_seed20260917.json');s2a=read('W1_CONFIRMATION_VA_seed20260917.json');unc=read('W1_ADAPTATION_UNCERTAINTY.json');prov=read('CHECKPOINT_PROVENANCE.json');compute=read('COMPUTE_SUMMARY.json')
