 P=cpu['outer_refit'];selected={'definition':'0.5 original iic/emotion2vec_base@v2.0.4 masked final-frame mean+std / StandardScaler / C1 multinomial logistic probabilities + 0.5 cached facebook/wav2vec2-xls-r-300m@1a640f32ac3e39899438a2931f9924c02f080a54 mean+std / StandardScaler / C1 multinomial logistic probabilities; ordinary argmax. Certified retrieval remains separate and unchanged.','deployment_status':'Preferred Wave1 candidate for SS review; accepted submitted control not modified','metrics':rowmetrics(P),'retrieval_aware_VA':cpu['retrieval_aware_VA']['FIXED_PAIR']['macro_f1']}
 cm=P['VB']['confusion'];errors=sum(sum(row) for row in cm)-sum(cm[k][k] for k in range(4));ns=cm[2][3]+cm[3][2]
 evidence={'status':phase,'mission':'RS-DEFHS-SYSTEM3-WAVE1-001','branch':'rs/system3-wave1-001','starting_sha':'d78da6037ec1b73bf210f562baa30ebb1b9fa9e6','report_source_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'preflight':'PASS','target_090_met':False,'selected_candidate':selected,'recipes':{k:rowmetrics(v) for k,v in recipes.items()},
 'promotion':{'preferred_deployment_components':['original frozen emotion2vec C1','original frozen XLSR C1','fixed equal-probability blend'],'not_promoted':['A1: no retained encoder adaptation','corrected Candidate_A: negative marginal gain','AST B0/B1/seed averaging as standalone deployment: much weaker than P','Candidate_B seed1/seed2/mean: fails registered marginal conventions'],'inconclusive':['nested fusion: VB +.0065466 and all5 fold deltas positive, but VA nonretrieval -.0032893 versus P'],'supported_finding':'AST adaptation improves its weak matched frozen comparator; seed averaging passes the old conservative conditional gate against seed1 B0, but does not earn strong-system membership.'},
 'scientific_robustness':{'fixed_pair_old_conservative_simultaneous_gate':'FAIL: VB simultaneous lower bound crosses zero','uncertainty':'conditional on reused ordinary-development OOF; VA/CLEAN and optimization seeds are related views, not independent cohorts','AST_old_gates':{k:v['old_conservative_gate_pass'] for k,v in unc['judgments'].items()},'reference':'W1_ADAPTATION_UNCERTAINTY.json and W1_NESTED_FUSION_RESULTS.json'},
 'competition_evidence':{'P_VB_gain':point(P)-point(cpu['control']),'P_VA_gain':point(P,'VA')-point(cpu['control'],'VA'),'P_VA_nonretrieval_gain':point(P,'VA','nonretrieval')-point(cpu['control'],'VA','nonretrieval'),'P_positive_VB_folds':sum(x>0 for x in P['VB']['fold_deltas']),'P_delete_fold_deltas':P['VB']['delete_fold_deltas'],'P_CLEAN_gain':P['VB']['strata']['CLEAN']['delta_vs_control'],'P_repairs':P['VB']['corrections'],'P_breakages':P['VB']['breakages'],'source_regime_limit':'int32 has small VB regression and positive VA direction; no routing and no automatic small-stratum veto'},
 'A_protocol_recovery':{'raw_refit_error':'Different numerical C1/scaler initializer in pilot/refit','repair':'Same verified pilot epoch-zero heads and exact train-only scaler restored for zero-step outer refits; no training/encoder inference repeated; original outputs retained','strict_matched_A0':point(corr['matched_frozen']),'strict_A1':point(corr['adapted_vs_matched_frozen']),'all_selected_epochs':[0]*5,'no_retained_encoder_updates':True,'stop_CE_parity':'PASS','reference':'W1_E2V_ADAPTATION_RESULTS.json:strict_same_initialization_correction'},
 'remaining_errors':{'P_VB_errors':errors,'neutral_sad_cross_errors':ns,'interpretation':'Largest measured confusion pair; no demonstrated label ambiguity, representation failure, or oracle ensemble ceiling'},'Wave2_trigger':'Target gaps remain after closure of all registered Wave1 comparisons. SS should supply/authorize the accepted Wave2 execution contract; no Wave2 work performed.','public_submission_recommendation':'Recommend SS review one controlled public test of uniform P; do not recommend new adaptation/AST members or claim 0.90 architecture success. No submission is authorized/performed here.','public_evidence':{'System1':.79691,'System2':.78593,'System2_verdict':'PUBLIC_TRANSFER_NEGATIVE','interpretation':'Post-diagnostic int32 Qwen gate failed fresh public transfer; old positive internal results preserved; private score unknown.','Wave1_public_score':None},'compute':compute,'Drive_root':'gdrive:DEFHS/rs_system3_wave1_001','preservation_closed':prov.get('preservation_closed',False),'protected_validation_read':False,'public_LB_used_for_selection':False,'Kaggle_competition_submission_made':False,'Wave2_or_Wave3_launched':False}
 if args.final:evidence['heavy_manifest_sha256']=sha256(RUN/'HEAVY_ARTIFACT_MANIFEST.json')
